const encounterId = "encounter.topic8.acceptance";
const now = 1_800_000_000_000;
const frozenOldCases=retired;
const priorRelease=beforeProgramBatch8AcceptanceRelease(current.clinicalRelease);
const previous: DomainContext = {...current, clinicalRelease:{...priorRelease,cases:[...priorRelease.cases.filter(cs=>!frozenOldCases.some(old=>old.id===cs.id)),...frozenOldCases]}};
type Frozen = GameState["encounters"][string]["frozenCase"];

function apply(state: GameState, command: GameCommand, context: DomainContext) {
  const next = gameReducer(state, command, context);
  expect(next.operationReceipts[command.operationId], command.operationId+": "+next.operationReceipts[command.operationId]?.message).toMatchObject({status:"applied"});
  return next;
}

function fixture(clinicalCase: SyntheticClinicalCase, context = current) {
  let state = clinicalCase.pediatricProfile ? createPediatricAppointmentsQaState(context,1) : createLevelFourRoomsQaState(context);
  const commands: GameCommand[] = [
    {type:"PLACE_ROOM", operationId:"topic8.exam", roomDefinitionId:"room.examination", roomId:"room.topic8.exam", x:35, y:24, orientation:0},
    {type:"PLACE_DOOR", operationId:"topic8.door", roomId:"room.topic8.exam", doorId:"door.topic8.exam", side:"south", offset:1},
  ];
  if (!clinicalCase.pediatricProfile) for (const command of commands) state = apply(state, command, context);
  if (clinicalCase.requiredCapabilityIds.includes("capability.minor_procedure")) {
    state = apply(state,{type:"PLACE_ROOM",operationId:"topic8.minor",roomDefinitionId:"room.minor_procedure",roomId:"room.topic8.minor",x:40,y:23,orientation:0},context);
    state = apply(state,{type:"PLACE_DOOR",operationId:"topic8.minor.door",roomId:"room.topic8.minor",doorId:"door.topic8.minor",side:"south",offset:1},context);
  }
  if (clinicalCase.requiredCapabilityIds.includes("capability.endoscopy")) {
    // The retired source requires a real staffed onsite service. Preserve that
    // requirement using the existing procedural fixture, not a capability stub.
    const clinic=endoscopyReadyClinic({appointments:false,provider:true},createInitialGameState(context));
    clinic.advance(60);
    state=clinic.state;
    state.facilityLevel=4;
    expect(getCurrentCapabilities(state,context).has("capability.endoscopy")).toBe(true);
  }
  Object.assign(state, {
    paused:false, nextRoutineArrivalTick:Number.MAX_SAFE_INTEGER, nextEmployeeDiscussionTick:Number.MAX_SAFE_INTEGER,
    nextFinancialPostingTick:Number.MAX_SAFE_INTEGER, serviceAppointmentsEnabled:false,
  });
  if (frozenOldCases.some(old => old.id === clinicalCase.id)) {
    const original=frozenOldCases.find(old=>old.id===clinicalCase.id)!;
    for (const node of original.decisionNodes) {
      const earlier = applyFsrsReview(createNewFsrsCard(0), "Good", 1000, context.balanceRelease.learning);
      state.learningHistories[node.primaryConceptId] = {
        conceptId:node.primaryConceptId, card:earlier.card,
        reviews:[{
          id:"review.topic8.previous." + node.id, encounterId:"encounter.topic8.previous", decisionNodeId:node.id,
          questionVariantId:node.questionVariantId, patientPresentationVariantId:clinicalCase.patientPresentationVariantId,
          primaryConceptId:node.primaryConceptId, answerChoiceId:node.answerChoices.find(choice => choice.isCorrect)!.id,
          correct:true, rating:"Good", reviewedAtMs:1000, facilityTick:0, schedulerLog:earlier.log,
        }],
      };
    }
  }
  const admission: GameCommand = {
    type:"ADMIT_PATIENT", operationId:"topic8.admit", encounterId, caseId:clinicalCase.id,
    patientDisplayName:(clinicalCase.pediatricProfile || retired.some(old=>old.id===clinicalCase.id))&&!clinicalCase.patientDisplayName.includes("{patientName}")
      ?clinicalCase.patientDisplayName:clinicalCase.prototypeDemographics?.sexLabel==="Female"?"Mira Vale":"Miles Vale",
    arrivalClass:"routine",
  };
  return {state, admission};
}

async function rig(state: GameState) {
  const clock = new TestCloudClock();
  const cache = new MemoryCloudCache();
  const entryStore = new MemoryCloudEntryStore();
  const scope = {backendId:"topic8.acceptance", accountId:"account-a", campaignId:state.campaignId};
  const server = new FakeCloudServer(clock.wallNow);
  server.setAccess(scope.accountId, {snapshotSaves:true});
  const copy = await snapshotCopy(state, codecTestCampaign(JSON.stringify(state)), "91", clock.wall,
    {branchId:"topic8.before", sequence:400, parents:[]});
  expect(copy.saveFormat).toBe(3);
  server.seed(scope.accountId, copy);
  const runtime = {...scope, region:"test", cache, entryStore, transport:server.transport(scope.accountId)};
  return {scope, clock, cache, copy, runtime, open:() => openAutomaticCloudCampaign({runtime, campaignId:scope.campaignId, clock})};
}

function preservedHistories(actual: GameState, old: GameState) {
  for (const [id, history] of Object.entries(old.learningHistories)) expect(actual.learningHistories[id], id).toEqual(history);
  for (const [id, history] of Object.entries(actual.learningHistories))
    if (!old.learningHistories[id]) expect(history.reviews, id).toEqual([]);
}

async function finish(session: CloudGameSession, frozen: Frozen) {
  const histories = structuredClone(session.state.learningHistories);
  const execute = (command: GameCommand) => {
    const next = session.execute(command, current);
    expect(next, command.operationId).not.toBeNull();
    expect(next!.operationReceipts[command.operationId], command.operationId).toMatchObject({status:"applied"});
    expect(session.syncView.failure).toBeNull();
    return next!;
  };
  for (let index = 0; index < frozen.decisionNodes.length; index++) {
    // Honor the actual pending service clock before measuring the existing
    // physical answer-readiness bound. Some retained external routes are300
    // minutes; they cannot be assessed with a240-minute travel budget.
    const pending = session.state.encounters[encounterId]!.pendingResult;
    if (pending && pending.dueTick > session.state.facilityTick) {
      const dueTick=pending.dueTick;
      const start=session.state.facilityTick;
      for(let elapsed=0;elapsed<dueTick-start;elapsed++) {
        execute({type:"ADVANCE_TICK",operationId:`topic8.service.${index}.${elapsed}`,advancedAtRealMs:now});
        if(elapsed%32===31)expect(await session.durable()).toBe(true);
      }
      expect(session.state.facilityTick).toBe(dueTick);
    }
    let question = getCurrentQuestion(session.state, encounterId, current);
    for (let tick = 0; tick < 240 && !question; tick++) {
      execute({type:"ADVANCE_TICK", operationId:`topic8.tick.${index}.${tick}`, advancedAtRealMs:now});
      const encounter = session.state.encounters[encounterId]!;
      if (session.state.openChartEncounterId !== encounterId && encounter.checkInStatus === "checked_in" && !encounter.patientMovement)
        execute({type:"OPEN_CHART", operationId:`topic8.open.${index}.${tick}`, encounterId});
      if (tick % 32 === 31) expect(await session.durable()).toBe(true);
      question = getCurrentQuestion(session.state, encounterId, current);
    }
    expect(question, "Frozen node reaches the existing240-tick readiness bound: "+JSON.stringify({
      tick:session.state.facilityTick,encounter:session.state.encounters[encounterId],
    })).not.toBeNull();
    const node = frozen.decisionNodes[index]!;
    expect(question!.node).toEqual(node);
    const classification = allTimings.find(entry => entry.caseId===frozen.id && entry.nodeId===node.id && entry.questionVariantId === node.questionVariantId)?.classification;
    if (classification) for (const choice of node.answerChoices) {
      const preview = getAnswerChoiceServicePreview(session.state, encounterId, choice.id, current);
      if (classification.kind === "no_test") {
        expect(preview).toBeNull();
        continue;
      }
      const expected = classification.choices.find(record => record.choiceId === choice.id)!.timing;
      if (expected.kind === "test") {
        expect(preview?.kind).toBe("test");
        expect(preview!.timingProfileId).toBe(expected.timingProfileId);
        expect(preview!.durationTicks).toBeGreaterThan(0);
      } else {
        expect(preview?.kind).toBe("no_test");
        expect(preview!.durationTicks).toBeNull();
      }
    }
    const answer: GameCommand = {
      type:"SUBMIT_ANSWER", operationId:`topic8.score.${index}`, encounterId, decisionNodeId:node.id,
      answerChoiceId:node.answerChoices.find(choice => choice.isCorrect)!.id, reviewedAtMs:now + index,
    };
    execute(answer);
    const history = session.state.learningHistories[node.primaryConceptId]!;
    const prior = histories[node.primaryConceptId]?.reviews ?? [];
    expect(history.reviews.slice(0,-1)).toEqual(prior);
    expect(history.reviews).toHaveLength(prior.length + 1);
    expect(history.reviews.at(-1)).toMatchObject({primaryConceptId:node.primaryConceptId, questionVariantId:node.questionVariantId, correct:true});
    expect(execute(answer).learningHistories[node.primaryConceptId]).toEqual(history);
    if (index < frozen.decisionNodes.length - 1)
      execute({type:"ACKNOWLEDGE_DECISION_FEEDBACK", operationId:`topic8.ack.${index}`, encounterId, decisionNodeId:node.id});
  }
  for (const [id, history] of Object.entries(histories))
    if (!frozen.decisionNodes.some(node => node.primaryConceptId === id)) expect(session.state.learningHistories[id]).toEqual(history);
  expect(session.state.encounters[encounterId]!.frozenCase).toEqual(frozen);
  expect(session.state.encounters[encounterId]!.answers).toHaveLength(frozen.decisionNodes.length);
  expect(session.state.encounters[encounterId]!.resolutionReason).toBe("completed");
  expect(session.canExecute).toBe(true);
  expect(session.needsReload).toBe(false);
  expect(await session.durable()).toBe(true);
}

describe("topic batch8 default admission and all retired frozen identities", () => {
  it.each(cases.filter(cs => cs.participant?.kind !== "employee_discussion"))("admits $id and completes its exact format3 save", async clinicalCase => {
    expect(current.clinicalRelease.cases.find(cs => cs.id === clinicalCase.id)).toEqual(clinicalCase);
    const f = fixture(clinicalCase);
    const state = apply(f.state, f.admission, current);
    const frozen = structuredClone(state.encounters[encounterId]!.frozenCase);
    if(clinicalCase.pediatricProfile){
      expect(frozen.prototypeDemographics).toEqual(clinicalCase.prototypeDemographics);
      const demographics=frozen.prototypeDemographics!;
      expect(pediatricStillEligibleEntries(demographics.sexLabel,demographics.ageYears).some(entry=>entry.stillId===state.encounters[encounterId]!.patientAppearance.stillId)).toBe(true);
      expect(state.encounters[encounterId]!.pediatricFamilyId).toBeTruthy();
      expect(state.retailExternalActors.filter(actor=>actor.kind==="companion"&&actor.linkedEncounterId===encounterId)).toHaveLength(1);
    }
    expect(frozen.presentation).toContain(state.encounters[encounterId]!.patientDisplayName);
    expect(state.learningHistories).toEqual(f.state.learningHistories);
    for (const node of frozen.decisionNodes) {
      const authored = materializePatientName(clinicalCase,state.encounters[encounterId]!.patientDisplayName).decisionNodes.find(original => original.id === node.id)!;
      expect([...node.answerChoices].sort((a,b) => a.id.localeCompare(b.id)))
        .toEqual([...authored.answerChoices].sort((a,b) => a.id.localeCompare(b.id)));
    }
    const r = await rig(state);
    let session = await CloudGameSession.create(await r.open(), undefined, undefined, {operational:false});
    try {
      expect(session.state.encounters[encounterId]!.frozenCase).toEqual(frozen);
      preservedHistories(session.state, state);
      await finish(session, frozen);
      expect(session.state.serviceOperations).toEqual([]);
      const done = session.state;
      session.dispose();
      session = await CloudGameSession.create(await r.open(), undefined, undefined, {operational:false});
      expect(session.state).toEqual(done);
      expect(session.state.encounters[encounterId]!.frozenCase).toEqual(frozen);
    } finally {
      session.dispose();
    }
  });

  it.each(frozenOldCases.filter(cs=>cs.participant?.kind!=="employee_discussion"))("reopens and completes retired $id with its original questions and FSRS identities", async clinicalCase => {
    expect(current.clinicalRelease.cases.find(cs=>cs.id===clinicalCase.id)).not.toEqual(clinicalCase);
    const f = fixture(clinicalCase, previous);
    expect(Object.keys(f.state.learningHistories)).toHaveLength(1105);
    const fresh=gameReducer(f.state,f.admission,current);
    if(!current.clinicalRelease.cases.some(cs=>cs.id===clinicalCase.id))expect(fresh.operationReceipts[f.admission.operationId]!.status).toBe("rejected");
    else {expect(fresh.operationReceipts[f.admission.operationId]!.status).toBe("applied");expect(fresh.encounters[encounterId]!.frozenCase.decisionNodes.map(n=>n.questionVariantId)).not.toEqual(clinicalCase.decisionNodes.map(n=>n.questionVariantId));}
    const state = apply(f.state, f.admission, previous);
    const frozen = structuredClone(state.encounters[encounterId]!.frozenCase);
    const r = await rig(state);
    const session = await CloudGameSession.create(await r.open(), undefined, undefined, {operational:false});
    try {
      expect(session.state.encounters[encounterId]!.frozenCase).toEqual(frozen);
      preservedHistories(session.state, state);
      await finish(session, frozen);
      for (const node of frozen.decisionNodes) expect(session.state.learningHistories[node.primaryConceptId]!.reviews)
        .toHaveLength(1+frozen.decisionNodes.filter(other=>other.primaryConceptId===node.primaryConceptId).length);
    } finally {
      session.dispose();
    }
  });

  it.each(frozenOldCases.filter(cs=>cs.participant?.kind!=="employee_discussion"))("replays the committed original admission journal for $id", async clinicalCase => {
    const f = fixture(clinicalCase, previous);
    const r = await rig(f.state);
    const coordinator = new CloudSyncCoordinator({...r.runtime, scope:r.scope, clock:r.clock, enabled:true});
    expect(await coordinator.open()).toBe(true);
    expect(await coordinator.startWriter()).toBe(true);
    expect(coordinator.resume()).toBe(true);
    const loaded = await loadCloudEvidenceCheckpoint({...r.copy, expectedRevision:"91", expectedCampaignId:f.state.campaignId, expectedBaselineId:r.copy.baselineId});
    const key = cloudCampaignStorageKey(r.scope);
    const owner = "topic8.previous-writer";
    const head = await bindJournal(r.cache.journal!, key, owner, {
      checkpoint:loaded.checkpoint, campaign:loaded.campaign, source:loaded.source, confirmed:r.copy, usageQuestions:[],
      writerGeneration:coordinator.journalWriterGeneration,
      snapshotPolicy:{lineage:{...loaded.snapshotLineage!, parents:[r.copy.snapshot.uncompressedSha256]}},
    }, cloudCodec);
    const drain = new LocalJournalDrain(r.cache.journal!, key, owner, head.highWater, error => {throw error;});
    const committed = applyGameEvidenceCommand(loaded.checkpoint, f.admission, previous);
    expect(committed.state.operationReceipts[f.admission.operationId]).toMatchObject({status:"applied"});
    const frozen = committed.state.encounters[encounterId]!.frozenCase;
    drain.accept({delta:gameEvidenceDelta(loaded.checkpoint, committed.checkpoint), campaign:loaded.campaign,
      usageQuestions:[], writerGeneration:coordinator.journalWriterGeneration});
    expect(await drain.drain()).toBe(true);
    drain.stop();
    coordinator.dispose();
    expect((await r.cache.journal!.read(key))!.rows).toHaveLength(1);
    const session = await CloudGameSession.create(await r.open(), undefined, undefined, {operational:false});
    try {
      expect(session.state.encounters[encounterId]!.frozenCase).toEqual(frozen);
      preservedHistories(session.state, committed.state);
      expect(session.state.operationReceipts[f.admission.operationId]).toEqual(committed.state.operationReceipts[f.admission.operationId]);
      await finish(session, frozen);
      expect((await prepareJournal(r.cache.journal!, key, cloudCodec, {local:true, encode:false}))!.state).toEqual(session.state);
    } finally {
      session.dispose();
    }
  });
});

import {readFileSync} from "node:fs";
import {createHash} from "node:crypto";
import {expect} from "vitest";
import type {SyntheticClinicalRelease,SyntheticClinicalCase,AnswerChoiceTimingRegistryEntry} from "./schema";
import type {QuestionShipManifest} from "./question-ship-manifest";

const read=(name:string)=>JSON.parse(readFileSync(new URL("../../../tools/question-quality/fixtures/"+name,import.meta.url),"utf8"));
const before=read("question-flags5-final-acceptance-before-20261116.json");
const after=read("question-flags5-final-acceptance-after-20261116.json");
const migration=read("question-flags5-final-acceptance-source-migration-20261116.json") as {files:Array<{path:string;beforeText:string;beforeSha256:string;afterSha256:string}>};
const earlierMigration=read("question-flags5-acceptance-source-migration-20261116.json") as typeof migration;
const sha=(s:string|Buffer)=>createHash("sha256").update(s).digest("hex"),hash=(v:unknown)=>sha(JSON.stringify(v));
const releaseCache=new WeakMap<SyntheticClinicalRelease,SyntheticClinicalRelease>();
const manifestCache=new WeakMap<QuestionShipManifest,QuestionShipManifest>();

/** Exact inverse for the final seven owner-directed flag fixes batch 5.
 * No old capture, clinical version, assertion or timing budget is relaxed. */
export function beforeFlags5FinalAcceptanceRelease(release:SyntheticClinicalRelease):SyntheticClinicalRelease {
  const actual=hash(release);
  if(actual===before.defaultSha256)return release;
  if(!release.cases.some(c=>c.decisionNodes.some(n=>after.acceptedQuestionIds.includes(n.questionVariantId))))return release;
  expect(actual,"complete final flags5 release postimage").toBe(after.defaultSha256);
  let prior=releaseCache.get(release);
  if(!prior){prior=structuredClone(before.defaultRelease) as SyntheticClinicalRelease;releaseCache.set(release,prior);}
  expect(hash(prior),"immutable sixteen-PASS release preimage").toBe(before.defaultSha256);
  return prior;
}
export function beforeFlags5FinalAcceptanceManifest<T extends QuestionShipManifest>(manifest:T):T {
  const actual=hash(manifest);
  if(actual===before.manifestSha256)return manifest;
  if(!manifest.accepted.some(r=>after.acceptedQuestionIds.includes(r.questionVariantId)))return manifest;
  expect(actual,"complete final flags5 authority postimage").toBe(after.manifestSha256);
  let prior=manifestCache.get(manifest);
  if(!prior){prior=structuredClone(before.manifest) as QuestionShipManifest;manifestCache.set(manifest,prior);}
  expect(hash(prior),"immutable sixteen-PASS authority preimage").toBe(before.manifestSha256);
  return prior as T;
}
export function beforeFlags5FinalAcceptanceTimings(entries:readonly AnswerChoiceTimingRegistryEntry[]):AnswerChoiceTimingRegistryEntry[] {
  if(!entries.some(t=>after.acceptedQuestionIds.includes(t.questionVariantId)))return [...entries];
  expect(hash(entries),"complete final flags5 wait postimage").toBe(after.timingSha256);
  expect(hash(before.timing),"immutable sixteen-PASS wait preimage").toBe(before.timingSha256);
  return structuredClone(before.timing);
}
export function beforeFlags5FinalAcceptanceCases(cases:readonly SyntheticClinicalCase[]):SyntheticClinicalCase[] {
  return cases.map(c=>{
    if(!c.decisionNodes.some(n=>after.acceptedQuestionIds.includes(n.questionVariantId)))return c;
    expect(hash(c),c.id+" exact final accepted case").toBe(after.caseHashes[c.id]);
    const prior=before.defaultRelease.cases.find((x:SyntheticClinicalCase)=>x.id===c.id)!;
    expect(hash(prior),c.id+" immutable preimage").toBe(before.caseHashes[c.id]);
    return structuredClone(prior);
  });
}
export function beforeFlags5FinalAcceptanceConcepts(concepts:SyntheticClinicalRelease["concepts"]):SyntheticClinicalRelease["concepts"] {
  if(!concepts.some(c=>after.newConceptIds.includes(c.id)))return concepts;
  for(const id of after.newConceptIds){const found=concepts.filter(c=>c.id===id);expect(found).toHaveLength(1);expect(hash(found[0])).toBe(after.conceptHashes[id]);}
  return concepts.filter(c=>!after.newConceptIds.includes(c.id));
}
export function beforeFlags5FinalAcceptanceSource(path:string,current:string):string {
  const row=migration.files.find(f=>f.path===path);
  if(!row||sha(current)===row.beforeSha256)return current;
  // Some historical guards already normalized the prior sixteen-PASS stage.
  // Accept only its immutable exact preimage, never an arbitrary older value.
  const prior=earlierMigration.files.find(f=>f.path===path&&f.afterSha256===row.beforeSha256&&f.beforeSha256===sha(current));
  if(prior){expect(sha(prior.beforeText),path+" immutable earlier-stage source preimage").toBe(prior.beforeSha256);return current;}
  expect(sha(current),path+" exact owner-directed flag fixes batch 5 final postimage").toBe(row.afterSha256);
  expect(sha(row.beforeText),path+" immutable source preimage").toBe(row.beforeSha256);
  return row.beforeText;
}
export function beforeFlags5FinalAcceptanceSourceBytes(value:string):string;
export function beforeFlags5FinalAcceptanceSourceBytes(value:Buffer):Buffer;
export function beforeFlags5FinalAcceptanceSourceBytes(value:string|Buffer):string|Buffer {
  const row=migration.files.find(f=>f.afterSha256===sha(value));
  if(!row)return value;
  expect(sha(row.beforeText),row.path+" immutable source bytes").toBe(row.beforeSha256);
  return Buffer.isBuffer(value)?Buffer.from(row.beforeText):row.beforeText;
}

import {describe,expect,it} from "vitest";
import {readFileSync} from "node:fs";
